import{_ as r,C as e,o,c as s,ae as n,E as i}from"./chunks/framework.EHGTsUvI.js";const f=JSON.parse('{"title":"Ключевые возможности","description":"","frontmatter":{},"headers":[],"relativePath":"ru/features.md","filePath":"ru/features.md"}'),u={name:"ru/features.md"};function d(_,a,c,h,p,m){const l=e("ApiMatrix"),t=e("PluginShowcase");return o(),s("div",null,[a[0]||(a[0]=n('<h1 id="ключевые-возможности" tabindex="-1">Ключевые возможности <a class="header-anchor" href="#ключевые-возможности" aria-label="Permalink to &quot;Ключевые возможности&quot;">​</a></h1><p>OTools объединяет интеграцию инструментов, экосистему плагинов и многозадачность Tabs в единую высокопроизводительную desktop‑платформу. Ниже — обзор основных возможностей.</p><h2 id="_1-многозадачность-tabs" tabindex="-1">1. Многозадачность Tabs <a class="header-anchor" href="#_1-многозадачность-tabs" aria-label="Permalink to &quot;1. Многозадачность Tabs&quot;">​</a></h2><ul><li>Открывайте несколько инструментов параллельно и сохраняйте контекст.</li><li>Быстро переключайтесь между плагинами без повторной загрузки.</li><li>Подходит для продуктивных рабочих процессов и снижает количество переключений окон.</li></ul><h2 id="_2-«океанская»-экосистема-плагинов" tabindex="-1">2. «Океанская» экосистема плагинов <a class="header-anchor" href="#_2-«океанская»-экосистема-плагинов" aria-label="Permalink to &quot;2. «Океанская» экосистема плагинов&quot;">​</a></h2><ul><li>Встроенные инструменты + плагины сообщества формируют полноценную экосистему.</li><li>Горячие обновления, история версий и дистрибуция через маркетплейс.</li><li>Единый каталог плагинов и точка управления.</li></ul><h2 id="_3-высокопроизводительныи-desktop‐runtime" tabindex="-1">3. Высокопроизводительный desktop‑runtime <a class="header-anchor" href="#_3-высокопроизводительныи-desktop‐runtime" aria-label="Permalink to &quot;3. Высокопроизводительный desktop‑runtime&quot;">​</a></h2><ul><li>Локальные вызовы — быстро и стабильно.</li><li>Поддержка Native‑динамических библиотек для увеличения производительности.</li><li>Единый API‑мост для согласованных вызовов.</li></ul><h2 id="_4-дружественно-к-разработчикам" tabindex="-1">4. Дружественно к разработчикам <a class="header-anchor" href="#_4-дружественно-к-разработчикам" aria-label="Permalink to &quot;4. Дружественно к разработчикам&quot;">​</a></h2><ul><li>Встроенный центр разработчика: создание, привязка, отладка.</li><li>Инициализация проектов Web/Vue и Rust‑Native одним кликом.</li><li>Полный процесс упаковки для распространения.</li></ul><h2 id="_5-встроенные-модули" tabindex="-1">5. Встроенные модули <a class="header-anchor" href="#_5-встроенные-модули" aria-label="Permalink to &quot;5. Встроенные модули&quot;">​</a></h2><ul><li>Управление Git‑проектами и документы с поддержкой ИИ</li><li>Сетевые инструменты HTTP / MQTT / FTP</li><li>Терминалы Docker и SSH/SFTP</li><li>Управление базами данных (DBM)</li><li>Захват и воспроизведение пакетов (Pakcap)</li><li>Скриншоты, аудио, дисковые утилиты и другое</li></ul>',12)),i(l),i(t)])}const P=r(u,[["render",d]]);export{f as __pageData,P as default};
